from build import put,render
def b(i,d,c,a,e,f,status='Partially addressed',kind='Methodological'):
 return dict(id=i,description=d,conditions=c,cause=a,evidence=e,kind=kind,followups=f,status=status,confidence='High within the stated experimental scope')
